function Json2Get(type) {var cont = $("#content").val();if (type == 1) {cont = cont.replace(/\t/g, "");cont = cont.replace(/\"/g, "").replace("{", "").replace("}", "").replace(",", "&").replace(":", "=");cont = cont.replace(/\"/g, "").replace(/{/g, "").replace(/}/g, "").replace(/,/g, "&").replace(/:/g, "=");} else {cont = cont.replace(/&/g, '","').replace(/;/g, '","').replace(/=/g, '":"');cont = '{"' + cont + '"}';}hightout(cont);}
